package com.chargedringreminder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ChargedRingPluginTest {

  public static void main(String[] args) throws Exception {
    ExternalPluginManager.loadBuiltin(ChargedRingPlugin.class);
    RuneLite.main(args);
  }
}

package com.chargedringreminder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ChargedRingConfig.GROUP)
public interface ChargedRingConfig extends Config {

  String GROUP = "chargedringreminder";

  @ConfigItem(
      keyName = "efaritaysAid",
      name = "Efaritay's aid",
      description =
          "Remind me when Efaritay's aid is not equipped. It has 200 charges against vampyric"
              + " targets and then shatters.",
      position = 1)
  default boolean efaritaysAid() {
    return false;
  }

  @ConfigItem(
      keyName = "ringOfRecoil",
      name = "Ring of recoil",
      description =
          "Remind me when a ring of recoil is not equipped. It reflects 40 damage and then"
              + " shatters.",
      position = 2)
  default boolean ringOfRecoil() {
    return false;
  }

  @ConfigItem(
      keyName = "ringOfForging",
      name = "Ring of forging",
      description =
          "Remind me when a ring of forging is not equipped. It lasts 140 iron smelts and then"
              + " crumbles to dust.",
      position = 3)
  default boolean ringOfForging() {
    return false;
  }

  @ConfigItem(
      keyName = "scale",
      name = "Scale",
      description = "Integer multiplier applied to each icon. Values of 0 or below are ignored.",
      position = 4)
  default int scale() {
    return 1;
  }
}

package com.chargedringreminder;

import com.chargedringreminder.overlays.ChargedRingOverlay;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(name = "Charged Ring Reminder")
public class ChargedRingPlugin extends Plugin {

  private static final int EFARITAYS_AID = 21140;
  private static final int RING_OF_RECOIL = 2550;
  private static final int RING_OF_FORGING = 2568;

  @Inject private Client client;

  @Inject private ChargedRingConfig config;

  @Inject private ChargedRingOverlay chargedRingOverlay;

  @Inject private OverlayManager overlayManager;

  private Set<Integer> watchedItemIds = Collections.emptySet();

  /** Read by the overlay on the client thread, written on the game tick. */
  private volatile List<Integer> missingItemIds = Collections.emptyList();

  @Override
  protected void startUp() {
    log.info("Charged Ring Reminder started!");
    updateWatchedItemIds();
    overlayManager.add(chargedRingOverlay);
  }

  @Override
  protected void shutDown() {
    log.info("Charged Ring Reminder stopped!");
    overlayManager.remove(chargedRingOverlay);
    missingItemIds = Collections.emptyList();
  }

  @Subscribe
  public void onConfigChanged(ConfigChanged event) {
    if (ChargedRingConfig.GROUP.equals(event.getGroup())) {
      updateWatchedItemIds();
    }
  }

  @Subscribe
  public void onGameTick(GameTick event) {
    if (watchedItemIds.isEmpty()) {
      return;
    }

    final ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
    if (equipment == null) {
      // No equipment container yet (e.g. on the login screen); keep the last known state
      // rather than claiming everything is missing.
      return;
    }

    final List<Integer> missing = new ArrayList<>(watchedItemIds.size());
    for (int itemId : watchedItemIds) {
      if (!equipment.contains(itemId)) {
        missing.add(itemId);
      }
    }
    this.missingItemIds = missing;
  }

  /** Watched item IDs that are not currently equipped, in the order they were configured. */
  public List<Integer> getMissingItemIds() {
    return missingItemIds;
  }

  /**
   * Only rings the user has explicitly enabled are watched, so someone who only cares about a ring
   * of recoil is never told about the others.
   *
   * <p>Deliberately limited to rings whose charges are tracked per player, so each has a single
   * item ID. Rings that carry their charges in the item itself, such as the ring of dueling or
   * ring of wealth, have a different ID per charge level and cannot be matched by a single ID.
   */
  private void updateWatchedItemIds() {
    final Set<Integer> itemIds = new LinkedHashSet<>();

    if (config.efaritaysAid()) {
      itemIds.add(EFARITAYS_AID);
    }
    if (config.ringOfRecoil()) {
      itemIds.add(RING_OF_RECOIL);
    }
    if (config.ringOfForging()) {
      itemIds.add(RING_OF_FORGING);
    }

    watchedItemIds = itemIds;
    // Recomputed on the next game tick.
    missingItemIds = Collections.emptyList();
  }

  @Provides
  ChargedRingConfig provideConfig(ConfigManager configManager) {
    return configManager.getConfig(ChargedRingConfig.class);
  }
}

