package com.chargedringreminder.overlays;

import com.chargedringreminder.ChargedRingConfig;
import com.chargedringreminder.ChargedRingPlugin;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

@Slf4j
public class ChargedRingOverlay extends Overlay {

  private final ChargedRingPlugin plugin;
  private final ChargedRingConfig config;
  private final ItemManager itemManager;

  /** Cached strip of icons, rebuilt only when the watched items, scale, or sprites change. */
  private ImageComponent cachedStrip;

  private String cachedStripKey;

  @Inject
  ChargedRingOverlay(ChargedRingPlugin plugin, ChargedRingConfig config, ItemManager itemManager)
      throws PluginInstantiationException {
    super(plugin);
    setPriority(OverlayPriority.MED);
    setPosition(OverlayPosition.BOTTOM_LEFT);
    setLayer(OverlayLayer.ALWAYS_ON_TOP);
    this.plugin = plugin;
    this.config = config;
    this.itemManager = itemManager;
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    final List<Integer> missingItemIds = plugin.getMissingItemIds();
    if (missingItemIds.isEmpty()) {
      return null;
    }

    final int scale = Math.max(1, config.scale());
    final String key = missingItemIds + "@" + scale;
    if (cachedStrip == null || !key.equals(cachedStripKey)) {
      final BufferedImage strip = buildStrip(missingItemIds, scale);
      if (strip == null) {
        return null;
      }
      cachedStrip = new ImageComponent(strip);
      cachedStripKey = key;
    }

    return cachedStrip.render(graphics);
  }

  /** Draws one icon per missing item, left to right, on a single transparent image. */
  private BufferedImage buildStrip(List<Integer> itemIds, int scale) {
    final List<BufferedImage> icons = new ArrayList<>(itemIds.size());
    for (int itemId : itemIds) {
      final AsyncBufferedImage source = itemManager.getImage(itemId);
      // Sprites load asynchronously. Drop the cached strip once the real pixels arrive so the
      // next render rebuilds it from the loaded image rather than a blank placeholder.
      source.onLoaded(() -> cachedStrip = null);
      icons.add(
          scale == 1
              ? source
              : ImageUtil.resizeImage(source, source.getWidth() * scale, source.getHeight() * scale));
    }

    int width = 0;
    int height = 0;
    for (BufferedImage icon : icons) {
      width += icon.getWidth();
      height = Math.max(height, icon.getHeight());
    }
    if (width <= 0 || height <= 0) {
      return null;
    }

    final BufferedImage strip = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    final Graphics2D stripGraphics = strip.createGraphics();
    int x = 0;
    for (BufferedImage icon : icons) {
      stripGraphics.drawImage(icon, x, 0, null);
      x += icon.getWidth();
    }
    stripGraphics.dispose();
    return strip;
  }
}
